server {
    listen 80;
    listen [::]:80;
    server_name set10-c.test www.set10-c.test;

    access_log /var/log/nginx/set10-c.test-access.log;
    error_log /var/log/nginx/set10-c.test-error.log;

    # Root-owned validation content only; never tenant public_html.
